        /// <summary>
        /// The Reload.
        /// </summary>
        /// <param name="source">The source<see cref="CollectionEntry"/>.</param>
        public static void Reload(this CollectionEntry source)
        {
            if (source.CurrentValue != null)
            {
                foreach (var item in source.CurrentValue)
                    source.EntityEntry.Context.Entry(item).State = EntityState.Detached;
                source.CurrentValue = null;
            }
            source.IsLoaded = false;
            source.Load();
        }

        /// <summary>
        /// The ReloadEntity.
        /// </summary>
        /// <param name="source">The source<see cref="EntityEntry"/>.</param>
        public static void ReloadEntity(this EntityEntry source)
        {
            source.Reload();
        }



        #endregion
    }

