        /// <summary>
        /// The DetachLocal.
        /// </summary>
        /// <typeparam name="T">.</typeparam>
        /// <param name="t">The t<see cref="T"/>.</param>
        /// <param name="Id">The Id<see cref="int?"/>.</param>
        public static void DetachLocal<T>(T t, int? Id) where T : ModelBase
        {
            var local = DataController.SandboxEntities.Set<T>().Local.FirstOrDefault(entry => entry.Id.Equals(Id));

            // check if local is not null 
            if (local != null)
            {
                // detach
                DataController.SandboxEntities.Entry(local).State = EntityState.Detached;
            }
        }

