        /// <summary>
        /// The GetMovie.
        /// </summary>
        /// <param name="Id">The Id<see cref="int"/>.</param>
        /// <returns>The <see cref="Movies?"/>.</returns>
        public Movies? GetMovie(int Id)
        {
            var id = new SqlParameter("Id", Id);

            var result = this.Movies.FromSql($"select * from Movies where id = {id} ").FirstOrDefault();

            // var mySeason = this.Movies.FromSql($"select season from Movies where id = {id} ").FirstOrDefault();

            if (result != null)
            {
                // load sub entities 
                if (result.Series != null)
                {
                    var seriesId = new SqlParameter("Id", result.Series);
                    result.SeriesEntity = this.Series.FromSql($" select * from Series where id = {seriesId}").FirstOrDefault();
                }

                if (result.Season != null)
                {
                    var seriesId = new SqlParameter("Id", result.Season);
                    result.SeasonEntity = this.Seasons.FromSql($" select * from Season where id = {seriesId}").FirstOrDefault();
                }

                if (result.Episode != null)
                {
                    var seriesId = new SqlParameter("Id", result.Episode);
                    result.EpisodeEntity = this.TVEpisodes.FromSql($" select * from TvEpisode where id = {seriesId}").FirstOrDefault();
                }

                if (result.DirectorID != null)
                {
                    var seriesId = new SqlParameter("Id", result.DirectorID);
                    result.Director = this.Directors.FromSql($" select * from Director where id = {seriesId}").FirstOrDefault();
                }
            }

            return result;
        }

